{"file_path":"/app/jump_analyzer.py","old_string":"def find_runner_start(comps_per_frame: list, width: int) -> tuple:
    """Locate the first frame where the runner enters the scene.

    Returns (start_index, initial_component, direction), where direction
    is -1 for right-to-left movement and +1 for left-to-right.
    """
    # Primary search: runner enters from the right edge (right-to-left).
    for i, comps in enumerate(comps_per_frame):
        candidates = [c for c in comps if c[0] > 2500 and c[6] > 0.7 * width and c[5] > 280]
        if candidates:
            sel = max(candidates, key=lambda c: c[0])
            return i, sel, -1
    # Fallback: runner may be approaching from the left edge.
    for i, comps in enumerate(comps_per_frame):
        candidates = [c for c in comps if c[0] > 2500 and c[6] < 0.3 * width and c[5] > 280]
        if candidates:
            sel = max(candidates, key=lambda c: c[0])
            return i, sel, +1
    # Last resort: largest plausible blob anywhere in the lower half.
    best_area = -1
    best_data = None
    for i, comps in enumerate(comps_per_frame):
        for c in comps:
            if c[0] > best_area and c[5] > 280:
                best_area = c[0]
                best_data = (i, c)
    if best_data is None:
        raise RuntimeError("Could not find a runner in the video")
